// ═══ WHY catch(Exception) IS DANGEROUS ═══

// (Avoid) BROAD catch hides bugs AND errors:
try {
    Trade trade = tradeRepository.findById(tradeId);  // might return null
    BigDecimal amount = trade.getAmount();              // NPE if null!
    settlementService.settle(trade);
} catch (Exception e) {
    log.error("Settlement failed", e);
    return "FAILED";
    // NullPointerException caught here! BUG HIDDEN!
    // You think: "settlement service had an issue"
    // Reality: YOUR code has a null bug at line 2!
}

// (Recommended) SPECIFIC catch — bug NOT hidden:
try {
    Trade trade = Objects.requireNonNull(tradeRepository.findById(tradeId));
    settlementService.settle(trade);
} catch (SettlementException e) {
    log.error("Settlement failed for {}", tradeId, e);
    return "FAILED";
}
// NullPointerException is NOT caught → crashes LOUDLY → bug found immediately!

// ═══ catch(Throwable) IS EVEN WORSE ═══
try {
    processLargeBatch();
} catch (Throwable t) {
    log.error("Batch failed", t);
    // Catches OutOfMemoryError! JVM is DYING but you're logging and continuing.
    // Catches StackOverflowError! Stack is blown but you "handle" it.
    // Catches ThreadDeath! Thread.stop() can't stop your thread.
    // The JVM is in an INCONSISTENT state — continuing is DANGEROUS.
}

// ═══ EXCEPTIONS FOR CONTROL FLOW — WRONG ═══

// (Avoid) WRONG: using exception to check if key exists
public BigDecimal getBalance(String accountId) {
    try {
        return accountMap.get(accountId);  // returns null if not found
    } catch (NullPointerException e) {
        return BigDecimal.ZERO;  // "handling" null as not found
    }
    // Slow: exception creation ~2μs. Unreadable. Hides REAL NPE bugs!
}

// (Recommended) CORRECT: use containsKey / Optional
public BigDecimal getBalance(String accountId) {
    return Optional.ofNullable(accountMap.get(accountId))
        .orElse(BigDecimal.ZERO);
    // Fast. Readable. No exception overhead. No hidden bugs.
}

// (Avoid) WRONG: looping with exception as termination
int i = 0;
try {
    while (true) {
        process(array[i++]);  // ArrayIndexOutOfBoundsException ends loop
    }
} catch (ArrayIndexOutOfBoundsException e) { }
// ~100x slower than for-loop. Unreadable. Prevents JIT optimization.

// (Recommended) CORRECT: normal loop
for (int i = 0; i < array.length; i++) {
    process(array[i]);
}

// (Avoid) WRONG: parseInt to check if string is numeric
public boolean isNumeric(String s) {
    try {
        Integer.parseInt(s);
        return true;
    } catch (NumberFormatException e) {
        return false;
    }
}
// Creates exception object + stack trace for EVERY non-numeric string!

// (Recommended) CORRECT: check without exception
public boolean isNumeric(String s) {
    return s != null && s.chars().allMatch(Character::isDigit);
}
