package com.bank.specificcatch;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.Map;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;

class SpecificCatchTest {

    // ═══ BROAD catch hides NullPointerException bug ═══
    @Test
    void broadCatch_hidesBug() {
        String result;
        try {
            String name = null;
            int len = name.length();  // NPE — a BUG!
            result = "OK";
        } catch (Exception e) {
            result = "FAILED";  // NPE caught! Bug HIDDEN! You think it's a "service error."
        }
        assertThat(result).isEqualTo("FAILED");
        // Developer never knows about the NPE → bug stays in production!
    }

    // ═══ SPECIFIC catch — bug surfaces ═══
    @Test
    void specificCatch_bugSurfaces() {
        assertThatThrownBy(() -> {
            String name = null;
            try {
                process(name);
            } catch (IllegalArgumentException e) {
                // Only catches business validation errors
            }
            // NPE from name.length() is NOT caught → propagates → bug found!
        }).isInstanceOf(NullPointerException.class);
    }

    private void process(String name) {
        int len = name.length();  // NPE if null — will NOT be caught by IllegalArgumentException catch
    }

    // ═══ DON'T use exception for control flow ═══
    @Test
    void controlFlow_exceptionVsCheck() {
        Map<String, BigDecimal> accounts = Map.of("SAV2001", new BigDecimal("50000"));

        // (Avoid) WRONG way: exception for missing key
        BigDecimal wrong;
        try {
            wrong = accounts.get("INVALID").add(BigDecimal.ZERO);
        } catch (NullPointerException e) {
            wrong = BigDecimal.ZERO;
        }

        // (Recommended) CORRECT way: check first
        BigDecimal correct = Optional.ofNullable(accounts.get("INVALID"))
            .orElse(BigDecimal.ZERO);

        assertThat(wrong).isEqualByComparingTo(correct);
        // Same result — but correct way is faster, cleaner, no hidden bug risk.
    }

    // ═══ Performance: exception vs if-check ═══
    @Test
    void performance_exceptionVsCheck() {
        int iterations = 50_000;
        Map<String, String> map = Map.of("key", "value");

        // Exception-based:
        long exStart = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            try {
                String v = map.get("missing");
                if (v == null) throw new RuntimeException();
            } catch (RuntimeException e) { }
        }
        long exTime = (System.nanoTime() - exStart) / 1_000_000;

        // Check-based:
        long chkStart = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            if (!map.containsKey("missing")) { /* not found */ }
        }
        long chkTime = (System.nanoTime() - chkStart) / 1_000_000;

        System.out.println("Exception: " + exTime + "ms, Check: " + chkTime + "ms");
        assertThat(chkTime).isLessThanOrEqualTo(exTime);
        // Exception: ~80ms. Check: ~1ms. ~80x faster!
    }
}
